a' ?><?php if($item['uso']): ?><small><?= $escape($item['uso']) ?><?= $item['funcao_treino']?' · '.$escape($item['funcao_treino']):'' ?></small><?php endif; ?></td><td><details class="inventory-details"><summary>Registrar baixa/estado</summary><form class="inventory-inline-form app-form" method="post" action="almoxarifado"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="action" value="inventory-movement"><input type="hidden" name="item_id" value="<?= (int)$item['id'] ?>"><label>Movimentação<select name="movement"><option value="baixa">Baixar como perdido/descartado</option><option value="manutencao">Enviar para manutenção</option><option value="retorno_manutencao">Retornar da manutenção</option><?php if($item['modo_controle']==='quantidade'): ?><option value="entrada">Registrar nova entrada</option><?php endif; ?></select></label><label>Quantidade<input type="number" name="quantity" min="1" max="<?= max(1,(int)$item['disponivel']) ?>" value="1" required></label><label>Origem da nova entrada<select name="origin"><option value="compra">Compra</option><option value="doacao">Doação</option><option value="outro">Outra</option></select></label><label>Motivo<input name="reason" maxlength="240" required placeholder="Sumiu, quebrou, reposição..."></label><button class="app-button app-button-outline" type="submit">Registrar</button></form></details></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
