    </section>

    <section class="inventory-panel" aria-labelledby="inventory-event-title"><div class="inventory-panel-heading"><div><p class="inventory-kicker">SAÍDA PARA JOGOS E AMISTOSOS</p><h2 id="inventory-event-title">Conferência por evento</h2><p>Monte a lista antes da saída e, na volta, informe o que foi devolvido, perdido ou danificado. A perda gera baixa e o dano envia o item à manutenção.</p></div></div><form class="inventory-form app-form" method="post" action="almoxarifado"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="action" value="create-checklist"><div class="app-field-grid"><label>Evento<select name="event_id" required><option value="">Selecione</option><?php foreach($inventory['events'] as $event): ?><option value="<?= (int)$event['id'] ?>"><?= $escape((new DateTimeImmutable((string)$event['inicio']))->format('d/m/Y H:i')) ?> · <?= $escape($event['titulo']) ?> (<?= $escape($event['tipo']) ?>)</option><?php endforeach; ?></select></label><label>Responsável pelo material<select name="custodian_id" required><option value="">Selecione</option><?php foreach($inventory['users'] as $user): ?><option value="<?= (int)$user['id'] ?>"><?= $escape($user['nome']) ?></option><?php endforeach; ?></select></label></div><h3>Itens para levar</h3><div class="inventory-checklist-builder" data-checklist-builder><div class="inventory-checklist-inputs" data-checklist-rows><div class="inventory-checklist-input" data-checklist-row><label>Item<select name="item_id[]" required><option value="">Selecione um item</option><?php foreach($availableItems as $item): ?><option value="<?= (int)$item['id'] ?>"><?= $escape($item['nome']) ?><?= $item['codigo']?' · '.$escape($item['codigo']):'' ?> · disp. <?= (int)$item['disponivel'] ?></option><?php endforeach; ?></select></label><label>Quantidade<input type="number" name="item_quantity[]" min="1" max="100000" value="1" required></label><button class="app-button app-button-outline inventory-row-button" type="button" data-remove-checklist-item aria-label="Remover item" title="Remover item" disabled><span aria-hidden="true">−</span></button></div></div><template data-checklist-template><div class="inventory-checklist-input" data-checklist-row><label>Item<select name="item_id[]" required><option value="">Selecione um item</option><?php foreach($availableItems as $item): ?><option value="<?= (int)$item['id'] ?>"><?= $escape($item['nome']) ?><?= $item['codigo']?' · '.$escape($item['codigo']):'' ?> · disp. <?= (int)$item['disponivel'] ?></option><?php endforeach; ?></select></label><label>Quantidade<input type="number" name="item_quantity[]" min="1" max="100000" value="1" required></label><button class="app-button app-button-outline inventory-row-button" type="button" data-remove-checklist-item aria-label="Remover item" title="Remover item"><span aria-hidden="true">−</span></button></div></template><div class="inventory-checklist-actions"><button class="app-button app-button-outline" type="button" data-add-checklist-item><span aria-hidden="true">+</span><span>Adicionar item</span></button></div><p class="inventory-visually-hidden" data-checklist-status role="status" aria-live="polite">1 item na lista.</p></div><label>Observação<input name="note" maxlength="240"></label><button class="app-button" type="submit" <?= $availableItems===[]||$inventory['events']===[]?'disabled':'' ?>>Criar lista e reservar itens</button></form>
        <?php if($inventory['checklists']===[]): ?><p class="inventory-empty">Nenhuma conferência de evento cadastrada.</p><?php else: ?><div class="inventory-checklist-list"><?php foreach($inventory['checklists'] as $checklist): ?><article class="inventory-checklist-card"><div class="inventory-panel-heading"><div><h3><?= $escape($checklist['evento']) ?></h3><p><?= $escape((new DateTimeImmutable((string)$checklist['inicio']))->format('d/m/Y H:i')) ?> · responsável: <?= $escape($checklist['responsavel']) ?></p></div><span class="inventory-status <?= $checklist['status']==='aberto'?'is-open':'is-returned' ?>"><?= $checklist['status']==='aberto'?'Aguardando retorno':'Conferido' ?></span></div><?php $lines=$inventory['checklistLines'][(int)$checklist['id']] ?? []; ?><?php if($checklist['status']==='aberto'): ?><form class="inventory-form app-form" method="post" action="almoxarifado"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="action" value="close-checklist"><input type="hidden" name="checklist_id" value="<?= (int)$checklist['id'] ?>"><div class="inventory-return-lines"><?php foreach($lines as $line): ?><fieldset class="inventory-return-line"><legend><?= $escape($line['item_nome']) ?><?= $line['codigo']?' · '.$escape($line['codigo']):'' ?> — levaram <?= (int)$line['quantidade_levar'] ?></legend><label>Devolvidos<input type="number" name="results[<?= (int)$line['id'] ?>][returned]" min="0" max="<?= (int)$line['quantidade_levar'] ?>" value="<?= (int)$line['quantidade_levar'] ?>" required></label><label>Perdidos<input type="number" name="results[<?= (int)$line['id'] ?>][lost]" min="0" max="<?= (int)$line['quantidade_levar'] ?>" value="0" required></label><label>Danificados<input type="number" name="results[<?= (int)$line['id'] ?>][damaged]" min="0" max="<?= (int)$line['quantidade_levar'] ?>" value="0" required></label><label>Observação<input name="results[<?= (int)$line['id'] ?>][note]" maxlength="240"></label></fieldset><?php endforeach; ?></div><label>Observação da conferência<input name="note" maxlength="240"></label><button class="app-button" type="submit">Conferir retorno</button></form><?php else: ?><p><?= (int)$checklist['total_itens'] ?> tipos de material · conferido em <?= $escape($formatDate(substr((string)$checklist['fechado_em'],0,10))) ?> por <?= $escape($checklist['criado_por_nome'] ?? 'equipe') ?></p><ul class="inventory-checklist-history"><?php foreach($lines as $line): ?><li><strong><?= $escape($line['item_nome']) ?><?= $line['codigo']?' · '.$escape($line['codigo']):'' ?></strong>: levaram <?= (int)$line['quantidade_levar'] ?>, voltaram <?= (int)$line['quantidade_devolvida'] ?>, perdidos <?= (int)$line['quantidade_perdida'] ?>, danificados <?= (int)$line['quantidade_danificada'] ?><?= $line['observacao']?' · '.$escape($line['observacao']):'' ?></li><?php endforeach; ?></ul><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
    </section>

    <section class="inventory-panel" aria-labelledby="inventory-movement-title"><div class="inventory-panel-heading"><div><p class="inventory-kicker">AUDITORIA</p><h2 id="inventory-movement-title">Histórico de movimentações</h2><p>Baixas e mudanças de estado não apagam o registro do item.</p></div></div><?php if($inventory['movements']===[]): ?><p class="inventory-empty">Nenhuma movimentação registrada.</p><?php else: ?><div class="inventory-table-wrap"><table class="inventory-table"><caption>Movimentações recentes</caption><thead><tr><th>Data</th><th>Item</th><th>Movimento</th><th>Quantidade / motivo</th><th>Registrado por</th></tr></thead><tbody><?php foreach($inventory['movements'] as $movement): ?><tr><td><?= $escape((new DateTimeImmutable((string)$movement['data_movimento']))->format('d/m/Y H:i')) ?></td><td><?= $escape($movement['item_nome']) ?><?= $movement['codigo']?'<small>'.$escape($movement['codigo']).'</small>':'' ?></td><td><?= $escape($movementNames[$movement['tipo']] ?? $movement['tipo']) ?></td><td><?= (int)$movement['quantidade'] ?><?= $movement['origem']?' · '.$escape($movement['origem']):'' ?><small><?= $escape($movement['motivo']) ?></small></td><td><?= $escape($movement['responsavel'] ?? 'Sistema') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</main>
